def friend_request_count(ages):
    counts=[0]*121
    for age in ages:counts[age]+=1
    return sum(counts[a]*(counts[b]-(a==b)) for a in range(1,121) for b in range(1,121) if not (b<=a*.5+7 or b>a or b>100>a))

